VALUES ('doc-09-mitre-attack-p0-23528', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The net start command can be used in [Net](https://attack.mitre.org/software/S0039) to find information about Windows services.(Citation: Savill 1999)", "external_references": [{"description": "Savill, J. (1999, March 4). Net.exe reference. Retrieved September 22, 2015.", "source_name": "Savill 1999", "url": "https://web.archive.org/web/20150511162820/http://windowsitpro.com/windows/netexe-reference"}], "id": "relationship--1d36c3e8-238f-46c6-9b20-9fb4cb5c75ba", "modified": "2026-04-29T14:23:05.944Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--03342581-f790-4f03-ba41-e82e67392e23", "spec_version": "2.1", "target_ref": "attack-pattern--322bad5a-1c49-4d23-ab79-76d641794afa", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23528', 0, 64, '09-mitre-attack', 'retrieved', '7CB6291080F29362D864F6372F4B2B53997A4EA9FBF0A12F1C73FB28B0FAC622', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
