VALUES ('doc-09-mitre-attack-p0-23531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Commands such as net use and net session can be used in [Net](https://attack.mitre.org/software/S0039) to gather information about network connections from a particular host.(Citation: Savill 1999)", "external_references": [{"description": "Savill, J. (1999, March 4). Net.exe reference. Retrieved September 22, 2015.", "source_name": "Savill 1999", "url": "https://web.archive.org/web/20150511162820/http://windowsitpro.com/windows/netexe-reference"}], "id": "relationship--4c94f67d-6662-44ea-be75-ded8b2dbfa00", "modified": "2026-04-29T14:23:06.030Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--03342581-f790-4f03-ba41-e82e67392e23", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23531', 0, 72, '09-mitre-attack', 'retrieved', 'F5910E7DFA15E58FBB9A8ADA57BEAF7A619CC6CDCB9519B3063376D441C913CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
