VALUES ('doc-09-mitre-attack-p0-23532', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The net use \\\\system\\share /delete command can be used in [Net](https://attack.mitre.org/software/S0039) to remove an established connection to a network share.(Citation: Technet Net Use)", "external_references": [{"description": "Microsoft. (n.d.). Net Use. Retrieved November 25, 2016.", "source_name": "Technet Net Use", "url": "https://technet.microsoft.com/bb490717.aspx"}], "id": "relationship--4e167937-d152-4c57-a7b7-e3b407470720", "modified": "2026-04-29T14:23:06.031Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--03342581-f790-4f03-ba41-e82e67392e23", "spec_version": "2.1", "target_ref": "attack-pattern--a750a9f6-0bde-4bb3-9aae-1e2786e9780c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23532', 0, 68, '09-mitre-attack', 'retrieved', 'F2CABC7FE2D9CCE61D165EC3FF7A7B2459A07F3B385724FC8FCB04FF85533C95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
