VALUES ('doc-09-mitre-attack-p0-23535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-05T20:58:24.680Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The `net localgroup` and `net group` commands in [Net](https://attack.mitre.org/software/S0039) can be used to add existing users to local and domain groups.(Citation: Microsoft Net Localgroup) (Citation: Microsoft Net Group)", "external_references": [{"description": "Microsoft. (2016, August 31). Net group. Retrieved August 5, 2024.", "source_name": "Microsoft Net Group", "url": "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/cc754051(v=ws.11)"}, {"description": "Microsoft. (2016, August 31). Net Localgroup. Retrieved August 5, 2024.", "source_name": "Microsoft Net Localgroup", "url": "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/cc725622(v=ws.11)"}], "id": "relationship--751ab02e-aef4-442b-8e3d-aa392c97be7e", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--03342581-f790-4f03-ba41-e82e67392e23", "spec_version": "2.1", "target_ref": "attack-pattern--3e6831b2-bf4c-4ae6-b328-2e7c6633b291", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23535', 0, 92, '09-mitre-attack', 'retrieved', '425774E510CFB9629B14117B498B15EA9BB9964999B32176D420468BC2220D80', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
