VALUES ('doc-09-mitre-attack-p0-23557', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T20:23:39.837Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NPPSPY](https://attack.mitre.org/software/S1131) captures credentials by recording them through an alternative network listener registered to the mpnotify.exe process, allowing for cleartext recording of logon information.(Citation: Huntress NPPSPY 2022)", "external_references": [{"description": "Dray Agha. (2022, August 16). Cleartext Shenanigans: Gifting User Passwords to Adversaries With NPPSPY. Retrieved May 17, 2024.", "source_name": "Huntress NPPSPY 2022", "url": "https://www.huntress.com/blog/cleartext-shenanigans-gifting-user-passwords-to-adversaries-with-nppspy"}], "id": "relationship--dc434717-4497-4832-a1ff-d8f376022ff4", "modified": "2026-04-29T14:23:06.226Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--0630d1a7-54da-4a48-a6af-eb8a62b13c17", "spec_version": "2.1", "target_ref": "attack-pattern--435dfb86-2697-4867-85b5-2fef496c0517", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23557', 0, 81, '09-mitre-attack', 'retrieved', 'C636880D19E60ED586B5369F7AD933CCCDD8B1E19DC5AD73573696C871DBDF02', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
