VALUES ('doc-09-mitre-attack-p0-23558', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T20:25:33.088Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NPPSPY](https://attack.mitre.org/software/S1131) captures user input into the Winlogon process by redirecting RPC traffic from legitimate listening DLLs within the operating system to a newly registered malicious item that allows for recording logon information in cleartext.(Citation: Huntress NPPSPY 2022)", "external_references": [{"description": "Dray Agha. (2022, August 16). Cleartext Shenanigans: Gifting User Passwords to Adversaries With NPPSPY. Retrieved May 17, 2024.", "source_name": "Huntress NPPSPY 2022", "url": "https://www.huntress.com/blog/cleartext-shenanigans-gifting-user-passwords-to-adversaries-with-nppspy"}], "id": "relationship--dd9677aa-d14a-427f-9b47-2ce722278344", "modified": "2026-04-29T14:23:06.228Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--0630d1a7-54da-4a48-a6af-eb8a62b13c17", "spec_version": "2.1", "target_ref": "attack-pattern--bb5a00de-e086-4859-a231-fa793f6797e2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23558', 0, 92, '09-mitre-attack', 'retrieved', 'D1105EB681B1E7CDC2660C125F529B1687ED48D6BA870ADCEBF7109D1088F054', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
