VALUES ('doc-09-mitre-attack-p0-23574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-01-26T18:52:35.710Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Diskpart](https://attack.mitre.org/software/S9002) can execute a disk partition script file, which attempts to mount a virtual hard disk.(Citation: Halcyon_CloakRansomware_Dec2024) [Diskpart](https://attack.mitre.org/software/S9002) can also assign and mount virtual disks.(Citation: Halcyon_CloakRansomware_Dec2024) ", "external_references": [{"description": "Halcyon RISE Team. (2024, December 12). Cloak Ransomware Variant Exhibits Advanced Persistence, Evasion and VHD Extraction Capabilities. Retrieved December 23, 2025.", "source_name": "Halcyon_CloakRansomware_Dec2024", "url": "https://www.halcyon.ai/blog/cloak-ransomware-variant-exhibits-advanced-persistence-evasion-and-vhd-extraction-capabilities"}], "id": "relationship--cef1859a-f4d6-42ca-9fa8-eb77b7ae6e7b", "modified": "2026-04-29T14:23:06.208Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--080f872e-f1a3-4d42-bb00-9eb55949f6a9", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23574', 0, 83, '09-mitre-attack', 'retrieved', '9B77AD45027CF54F5444B71FAEB8E554FECA3F3CE1A9CAC6CE33BF91CEEA4E7F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
