VALUES ('doc-09-mitre-attack-p0-23575', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-01-26T18:52:58.619Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If executed with elevated privileges, [Diskpart](https://attack.mitre.org/software/S9002) can list all volumes, including virtual disks.(Citation: Halcyon_CloakRansomware_Dec2024) ", "external_references": [{"description": "Halcyon RISE Team. (2024, December 12). Cloak Ransomware Variant Exhibits Advanced Persistence, Evasion and VHD Extraction Capabilities. Retrieved December 23, 2025.", "source_name": "Halcyon_CloakRansomware_Dec2024", "url": "https://www.halcyon.ai/blog/cloak-ransomware-variant-exhibits-advanced-persistence-evasion-and-vhd-extraction-capabilities"}], "id": "relationship--f7f5185d-3e7a-4b5c-8a54-44eac8083780", "modified": "2026-04-29T14:23:06.262Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--080f872e-f1a3-4d42-bb00-9eb55949f6a9", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23575', 0, 71, '09-mitre-attack', 'retrieved', 'F804B2F0BBF983E9A0BB5C881F8D1E9C22CDA9790BF0CE66F4EAA7D6B43DBB5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
