VALUES ('doc-09-mitre-attack-p0-23576', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-03T00:40:22.063Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[certutil](https://attack.mitre.org/software/S0160) may be used to Base64 encode collected data.(Citation: TechNet Certutil)(Citation: LOLBAS Certutil)", "external_references": [{"description": "LOLBAS. (n.d.). Certutil.exe. Retrieved July 31, 2019.", "source_name": "LOLBAS Certutil", "url": "https://lolbas-project.github.io/lolbas/Binaries/Certutil/"}, {"description": "Microsoft. (2012, November 14). Certutil. Retrieved July 3, 2017.", "source_name": "TechNet Certutil", "url": "https://technet.microsoft.com/library/cc732443.aspx"}], "id": "relationship--0f5462cb-ac39-49d1-848e-aefaaab321e3", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--0a68f1f1-da74-4d28-8d9a-696c082706cc", "spec_version": "2.1", "target_ref": "attack-pattern--00f90846-cbd1-4fc5-9233-df5c2bf2a662", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23576', 0, 71, '09-mitre-attack', 'retrieved', '195FEEDC2D57CC81E5332227925C178B408425ABD67EA08AA9F14AAF58016E5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
