VALUES ('doc-09-mitre-attack-p0-23586', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-12T21:44:40.843Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShimRatReporter](https://attack.mitre.org/software/S0445) listed all non-privileged and privileged accounts available on the machine.(Citation: FOX-IT May 2016 Mofang)", "external_references": [{"description": "Yonathan Klijnsma. (2016, May 17). Mofang: A politically motivated information stealing adversary. Retrieved May 12, 2020.", "source_name": "FOX-IT May 2016 Mofang", "url": "https://foxitsecurity.files.wordpress.com/2016/06/fox-it_mofang_threatreport_tlp-white.pdf"}], "id": "relationship--52741f41-28c6-4533-bd26-6dc21f6b0794", "modified": "2026-04-29T14:23:06.038Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--115f88dd-0618-4389-83cb-98d33ae81848", "spec_version": "2.1", "target_ref": "attack-pattern--72b74d71-8169-42aa-92e0-e7b04b9f5a08", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23586', 0, 69, '09-mitre-attack', 'retrieved', 'AF80D9CB6C5A9EEA183B24031264A80743F46351FC802F1D2D02D1FEBE6D5953', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
