VALUES ('doc-09-mitre-attack-p0-23607', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-24T16:13:16.833Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sliver](https://attack.mitre.org/software/S0633) has a built-in SOCKS5 proxying capability allowing for [Sliver](https://attack.mitre.org/software/S0633) clients to proxy network traffic through other clients within a victim network.(Citation: Cybereason Sliver Undated)", "external_references": [{"description": "Cybereason Global SOC and Incident Response Team. (n.d.). Sliver C2 Leveraged by Many Threat Actors. Retrieved March 24, 2025.", "source_name": "Cybereason Sliver Undated", "url": "https://www.cybereason.com/blog/sliver-c2-leveraged-by-many-threat-actors"}], "id": "relationship--7fde1ea2-8561-4df3-8760-78d65601e305", "modified": "2026-04-29T14:23:06.100Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--11f8d7eb-1927-4806-9267-3a11d4d4d6be", "spec_version": "2.1", "target_ref": "attack-pattern--f6dacc85-b37d-458e-b58d-74fc4bbf5755", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23607', 0, 81, '09-mitre-attack', 'retrieved', 'F6FBAEADF1CDF6CDC4D47E12ABF2C23B1234BE2615641213466C8E7897079FEE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
