VALUES ('doc-09-mitre-attack-p0-23609', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-16T20:22:34.601Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sliver](https://attack.mitre.org/software/S0633) can take screenshots of the victim’s active display.(Citation: GitHub Sliver Screen)", "external_references": [{"description": "BishopFox. (n.d.). Sliver Screenshot. Retrieved September 16, 2021.", "source_name": "GitHub Sliver Screen", "url": "https://github.com/BishopFox/sliver/blob/master/implant/sliver/screen/screenshot_windows.go"}], "id": "relationship--8bcc4714-800c-4d13-8b85-2bdf107f5fb4", "modified": "2026-04-29T14:23:06.116Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--11f8d7eb-1927-4806-9267-3a11d4d4d6be", "spec_version": "2.1", "target_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23609', 0, 57, '09-mitre-attack', 'retrieved', '976992CDA64566EC169DD57AC5B334F5BE1D08A546FD8262B9312A2CC034CC0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
