VALUES ('doc-09-mitre-attack-p0-23610', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-30T15:49:45.832Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [Sliver](https://attack.mitre.org/software/S0633) has the ability to support C2 communications over HTTP and HTTPS.(Citation: Cybersecurity Advisory SVR TTP May 2021)(Citation: Bishop Fox Sliver Framework August 2019)(Citation: GitHub Sliver C2)(Citation: Cybereason Sliver Undated)(Citation: Microsoft Sliver 2022)", "external_references": [{"description": "BishopFox. (n.d.). Sliver. Retrieved September 15, 2021.", "source_name": "GitHub Sliver C2", "url": "https://github.com/BishopFox/sliver/"}, {"description": "Cybereason Global SOC and Incident Response Team. (n.d.). Sliver C2 Leveraged by Many Threat Actors. Retrieved March 24, 2025.", "source_name": "Cybereason Sliver Undated", "url": "https://www.cybereason.com/blog/sliver-c2-leveraged-by-many-threat-actors"}, {"description": "Kervella, R. (2019, August 4). Cross-platform General Purpose Implant Framework Written in Golang. Retrieved July 30, 2021.", "source_name": "Bishop Fox Sliver Framework August 2019", "url": "https://labs.bishopfox.com/tech-blog/sliver"}, {"description": "Microsoft Security Experts. (2022, August 24). Looking for the ‘Sliver’ lining: Hunting for emerging command-and-control frameworks. Retrieved March 24, 2025.", "source_name": "Microsoft Sliver 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/08/24/looking-for-the-sliver-lining-hunting-for-emerging-command-and-control-frameworks/"}, {"description": "NCSC, CISA, FBI, NSA. (2021, May 7). Further TTPs associated with SVR cyber actors. Retrieved July 29, 2021.", "source_name": "Cybersecurity Advisory SVR TTP May 2021", "url": "https://www.ncsc.gov.uk/files/Advisory-further-TTPs-associated-with-SVR-cyber-actors.pdf"}], "id": "relationship--8ed083f5-5fb2-4dbe-bb59-0a77b63e4a18", "modified": "2026-04-29T14:23:06.120Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--11f8d7eb-1927-4806-9267-3a11d4d4d6be", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23610', 0, 186, '09-mitre-attack', 'retrieved', '0014DA3045B3ABCE9B3084148638F144029F44089354BDBAF76177DB160A45B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
