VALUES ('doc-09-mitre-attack-p0-23614', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-24T16:12:00.919Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sliver](https://attack.mitre.org/software/S0633) incorporates the [Rubeus](https://attack.mitre.org/software/S1071) framework to allow for Kerberos ticket manipulation, specifically for forging Kerberos Golden Tickets.(Citation: Cybereason Sliver Undated)", "external_references": [{"description": "Cybereason Global SOC and Incident Response Team. (n.d.). Sliver C2 Leveraged by Many Threat Actors. Retrieved March 24, 2025.", "source_name": "Cybereason Sliver Undated", "url": "https://www.cybereason.com/blog/sliver-c2-leveraged-by-many-threat-actors"}], "id": "relationship--c2efefa6-e1e8-4817-9e62-70ba100e9432", "modified": "2026-04-29T14:23:06.192Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--11f8d7eb-1927-4806-9267-3a11d4d4d6be", "spec_version": "2.1", "target_ref": "attack-pattern--768dce68-8d0d-477a-b01d-0eea98b963a1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23614', 0, 76, '09-mitre-attack', 'retrieved', '02075D36CF3ECAA4B8675275FCBEEF2602821512B16084D3FDC023DCAD0DE4EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
