VALUES ('doc-09-mitre-attack-p0-23617', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-16T19:47:34.256Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sliver](https://attack.mitre.org/software/S0633) can use standard encoding techniques like gzip and hex to ASCII to encode the C2 communication payload.(Citation: GitHub Sliver HTTP)", "external_references": [{"description": "BishopFox. (n.d.). Sliver HTTP(S) C2. Retrieved September 16, 2021.", "source_name": "GitHub Sliver HTTP", "url": "https://github.com/BishopFox/sliver/wiki/HTTP(S)-C2"}], "id": "relationship--df2a0a3b-1a23-4148-a0f7-ed5b45a0d095", "modified": "2026-04-29T14:23:06.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--11f8d7eb-1927-4806-9267-3a11d4d4d6be", "spec_version": "2.1", "target_ref": "attack-pattern--04fd5427-79c7-44ea-ae13-11b24778ff1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23617', 0, 67, '09-mitre-attack', 'retrieved', '5C2B8C87445B02E5021CBFD8317685C3D69AAF2C5972FF8D1F1AE800E7FEAB14', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
