VALUES ('doc-09-mitre-attack-p0-23641', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-24T19:39:24.736Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SILENTTRINITY](https://attack.mitre.org/software/S0692) can use the `GetRegValue` function to check Registry keys within `HKCU\\Software\\Policies\\Microsoft\\Windows\\Installer\\AlwaysInstallElevated` and `HKLM\\Software\\Policies\\Microsoft\\Windows\\Installer\\AlwaysInstallElevated`. It also contains additional modules that can check software AutoRun values and use the Win32 namespace to get values from HKCU, HKLM, HKCR, and HKCC hives.(Citation: GitHub SILENTTRINITY Modules July 2019)", "external_references": [{"description": "Salvati, M. (2019, August 6). SILENTTRINITY Modules. Retrieved March 24, 2022.", "source_name": "GitHub SILENTTRINITY Modules July 2019", "url": "https://github.com/byt3bl33d3r/SILENTTRINITY/tree/master/silenttrinity/core/teamserver/modules/boo"}], "id": "relationship--75a89128-fcdd-4bcf-98a7-9f0ea162a794", "modified": "2026-04-29T14:23:06.086Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1244e058-fa10-48cb-b484-0bcf671107ae", "spec_version": "2.1", "target_ref": "attack-pattern--c32f7008-9fea-41f7-8366-5eb9b74bd896", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23641', 0, 95, '09-mitre-attack', 'retrieved', '96EEC32390BBAB6024CA5C9DC92AB0AB3982A37AB5F2A86FF1C0E125F29AFCA4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
