VALUES ('doc-09-mitre-attack-p0-23721', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-28T13:26:54.930Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pacu](https://attack.mitre.org/software/S1091) can set up S3 bucket notifications to trigger a malicious Lambda function when a CloudFormation template is uploaded to the bucket. It can also create Lambda functions that trigger upon the creation of users, roles, and groups.(Citation: GitHub Pacu)", "external_references": [{"description": "Rhino Security Labs. (2019, August 22). Pacu. Retrieved October 17, 2019.", "source_name": "GitHub Pacu", "url": "https://github.com/RhinoSecurityLabs/pacu"}], "id": "relationship--804f7690-6bf2-41dc-a6d2-59c3d4394ce5", "modified": "2026-08-04T20:30:56.831Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1b3b8f96-43b1-4460-8e02-1f53d7802fb9", "spec_version": "2.1", "target_ref": "attack-pattern--b6301b64-ef57-4cce-bb0b-77026f14a8db", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23721', 0, 87, '09-mitre-attack', 'retrieved', 'B7907A83CE33E823EE99DCB2FAE126B7A5D0F6045A7A4EEEE43D110D22136B9E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
