VALUES ('doc-09-mitre-attack-p0-23723', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-04T20:22:33.798Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) has the ability to hide phishing lures for a set time to avoid scanning by sandboxes.(Citation: Breakdev Evilginx 3.2 AUG 2023)", "external_references": [{"description": "Gretzky, K. (2023, August 24). Evilginx 3.2 - Swimming With The Phishes. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 3.2 AUG 2023", "url": "https://breakdev.org/evilginx-3-2/"}], "id": "relationship--2dc94895-c81e-4a83-865a-e53352f17395", "modified": "2026-04-29T14:23:05.966Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--4bed873f-0b7d-41d4-b93a-b6905d1f90b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23723', 0, 77, '09-mitre-attack', 'retrieved', '5CD064D85524E568C6F0D10E957FC1FC39C7D6AE3330714FA6CA396373D2CF29', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
