VALUES ('doc-09-mitre-attack-p0-23724', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-04T19:11:54.392Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) can reject requests to phishing URLs if the User-Agent of the visitor doesn''t match the allowlist REGEX filter for a specific lure.(Citation: Breakdev Evilginx 2.4 SEP 2020)", "external_references": [{"description": "Gretzky, K. (2020, September 14). Evilginx 2.4 - Gone Phishing. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 2.4 SEP 2020", "url": "https://breakdev.org/evilginx-2-4-gone-phishing/"}], "id": "relationship--3a749db3-cabf-4849-a9e4-a7ba21bfbd1f", "modified": "2026-04-29T14:23:06.001Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23724', 0, 81, '09-mitre-attack', 'retrieved', '76BCC6776E68A82B0F5DC6A3866DAC105AE80E885A25254FC26373361F5B83C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
