VALUES ('doc-09-mitre-attack-p0-23727', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-01-30T21:04:25.196Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) has the ability to act as an adversary-in-the-middle (AiTM) relay between a legitimate website and a phished user to capture all transmitted data including usernames, passwords, authentication tokens, and session cookies and tokens.(Citation: Evilginx 2 July 2018)(Citation: Breakdev Evilginx 3.0 May 2023)(Citation: Breakdev Evilginx 3.2 AUG 2023)(Citation: Sophos Evilginx MAR 2025)", "external_references": [{"description": "Everts, M. (2025, March 28). Stealing user credentials with evilginx. Retrieved January 27, 2026.", "source_name": "Sophos Evilginx MAR 2025", "url": "https://www.sophos.com/en-us/blog/stealing-user-credentials-with-evilginx"}, {"description": "Gretzky, K. (2023, August 24). Evilginx 3.2 - Swimming With The Phishes. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 3.2 AUG 2023", "url": "https://breakdev.org/evilginx-3-2/"}, {"description": "Gretzky, K. (2023, May 10). Evilginx 3.0 + Evilginx Mastery. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 3.0 May 2023", "url": "https://breakdev.org/evilginx-3-0-evilginx-mastery/"}, {"description": "Gretzky, K.. (2018, July 26). Evilginx 2 - Next Generation of Phishing 2FA Tokens. Retrieved October 14, 2019.", "source_name": "Evilginx 2 July 2018", "url": "https://breakdev.org/evilginx-2-next-generation-of-phishing-2fa-tokens/"}], "id": "relationship--719d58cc-72c9-44f9-9c4f-5a6d275eedfa", "modified": "2026-04-29T14:23:06.080Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--035bb001-ab69-4a0b-9f6c-2de8b09e1b9d", "type": "