VALUES ('doc-09-mitre-attack-p0-23728', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-03T20:23:34.419Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) can inject custom POST arguments into requests to silently enable \"Remember Me\" options during authentication to stay logged in across browser sessions.(Citation: Breakdev Evilginx 2.2 NOV 2018)", "external_references": [{"description": "Gretzky, K. (2018, November 22). Evilginx 2.2 - Jolly Winter Update. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 2.2 NOV 2018", "url": "https://breakdev.org/evilginx-2-2-jolly-winter-update"}], "id": "relationship--7641ab63-39e1-4cd2-8e9c-9bd1ce6da370", "modified": "2026-04-29T14:23:06.087Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--544b0346-29ad-41e1-a808-501bb4193f47", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23728', 0, 82, '09-mitre-attack', 'retrieved', '5F5A78586AF8EB0456488F1A06D2280EB03796DF05872E809338736447D2C270', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
