VALUES ('doc-09-mitre-attack-p0-23730', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-04T19:32:20.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) can randomly generate and Base64 encode parameters in phishing links to defeat static detection.(Citation: Breakdev Evilginx 2.4 SEP 2020)", "external_references": [{"description": "Gretzky, K. (2020, September 14). Evilginx 2.4 - Gone Phishing. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 2.4 SEP 2020", "url": "https://breakdev.org/evilginx-2-4-gone-phishing/"}], "id": "relationship--840d01e8-e401-413b-bdc8-f47122c5661d", "modified": "2026-04-29T14:23:06.106Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--cc7b8c4e-9be0-47ca-b0bb-83915ec3ee2f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23730', 0, 73, '09-mitre-attack', 'retrieved', '66418FE1B397ECC2A03FF82998DC9AD3B524AA941100812253860926ABF9035F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
