VALUES ('doc-09-mitre-attack-p0-23732', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-01-30T21:39:14.137Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) can route traffic via SOCKS5 and HTTP(S) proxies between an intended phishing victim''s machine and legitimate websites.(Citation: Evilginx 2 July 2018)(Citation: Breakdev Evilginx 2.4 SEP 2020)(Citation: Sophos Evilginx MAR 2025)\n", "external_references": [{"description": "Everts, M. (2025, March 28). Stealing user credentials with evilginx. Retrieved January 27, 2026.", "source_name": "Sophos Evilginx MAR 2025", "url": "https://www.sophos.com/en-us/blog/stealing-user-credentials-with-evilginx"}, {"description": "Gretzky, K. (2020, September 14). Evilginx 2.4 - Gone Phishing. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 2.4 SEP 2020", "url": "https://breakdev.org/evilginx-2-4-gone-phishing/"}, {"description": "Gretzky, K.. (2018, July 26). Evilginx 2 - Next Generation of Phishing 2FA Tokens. Retrieved October 14, 2019.", "source_name": "Evilginx 2 July 2018", "url": "https://breakdev.org/evilginx-2-next-generation-of-phishing-2fa-tokens/"}], "id": "relationship--a3a71677-e8d4-4d56-8429-50c3ec8fac85", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--69b8fd78-40e8-4600-ae4d-662c9d7afdb3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23732', 0, 132, '09-mitre-attack', 'retrieved', 'E5DB86D34B53951A20558A71522466C505A5E8CDA7B76B20188CC4F47D5BD98F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
