VALUES ('doc-09-mitre-attack-p0-23734', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-03T20:35:47.176Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) can generate and display phishing URLs including hidden tracking pixels and can also embed URLs within iframes for browser-in-the-browser phishing.(Citation: Breakdev Evilginx 2.3 JAN 2019)(Citation: Breakdev Evilginx 3.3 APR 2024)(Citation: Sophos Evilginx MAR 2025)\n", "external_references": [{"description": "Everts, M. (2025, March 28). Stealing user credentials with evilginx. Retrieved January 27, 2026.", "source_name": "Sophos Evilginx MAR 2025", "url": "https://www.sophos.com/en-us/blog/stealing-user-credentials-with-evilginx"}, {"description": "Gretzky, K. (2019, January 18). Evilginx 2.3 - Phisherman''s Dream. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 2.3 JAN 2019", "url": "https://breakdev.org/evilginx-2-3-phishermans-dream/"}, {"description": "Gretzky, K. (2024, April 2). Evilginx 3.3 - Go & Phish. Retrieved January 27, 2026.", "source_name": "Breakdev Evilginx 3.3 APR 2024", "url": "https://breakdev.org/evilginx-3-3-go-phish/"}], "id": "relationship--d6270a34-0a0b-456d-9857-f6fe0ec54ea8", "modified": "2026-04-29T14:23:06.218Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--2d3f5b3c-54ca-4f4d-bb1f-849346d31230", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23734', 0, 134, '09-mitre-attack', 'retrieved', '847876EE5684E6D0A745EC9A8EE6F9DF0E4AC32BBBE25747997FC817308C82DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
