VALUES ('doc-09-mitre-attack-p0-23735', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-02-03T19:58:46.562Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[evilginx2](https://attack.mitre.org/software/S9003) can modify the Origin and Referrer fields in HTTPS headers it relays between intended victims and legitimate websites to comply with cross-origin resource sharing (CORS) restrictions.(Citation: Evilginx 2 July 2018)", "external_references": [{"description": "Gretzky, K.. (2018, July 26). Evilginx 2 - Next Generation of Phishing 2FA Tokens. Retrieved October 14, 2019.", "source_name": "Evilginx 2 July 2018", "url": "https://breakdev.org/evilginx-2-next-generation-of-phishing-2fa-tokens/"}], "id": "relationship--dc27cb61-8dcf-4cc6-b166-b6faf6504c21", "modified": "2026-04-29T14:23:06.226Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--1eb9627d-a661-4db6-bf53-41b7dcc63087", "spec_version": "2.1", "target_ref": "attack-pattern--ad255bfe-a9e6-4b52-a258-8d3462abe842", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23735', 0, 87, '09-mitre-attack', 'retrieved', 'A272327030AD7ABE1BA064F715EF067B4FDF645012C535B5B5D090D4E27E282C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
