VALUES ('doc-09-mitre-attack-p0-23736', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Windows Credential Editor](https://attack.mitre.org/software/S0005) can dump credentials.(Citation: Amplia WCE)", "external_references": [{"description": "Amplia Security. (n.d.). Windows Credentials Editor (WCE) F.A.Q.. Retrieved September 12, 2024.", "source_name": "Amplia WCE", "url": "https://web.archive.org/web/20240904163410/https://www.ampliasecurity.com/research/wcefaq.html"}], "id": "relationship--935971d6-0af2-4683-971a-9acb523733fe", "modified": "2026-04-29T14:23:06.126Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--242f3da3-4425-4d11-8f5c-b842886da966", "spec_version": "2.1", "target_ref": "attack-pattern--65f2d882-3f41-4d48-8a06-29af77ec9f90", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23736', 0, 56, '09-mitre-attack', 'retrieved', '2E81D98D0D9F6471C0ECAB08679C90F536EC800DDDD1A6EC3B2DEA9B60A29080', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
