VALUES ('doc-09-mitre-attack-p0-23737', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-07T19:13:01.960Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Impacket](https://attack.mitre.org/software/S0357) modules like ntlmrelayx and smbrelayx can be used in conjunction with [Network Sniffing](https://attack.mitre.org/techniques/T1040) and [Name Resolution Poisoning and SMB Relay](https://attack.mitre.org/techniques/T1557/001) to gather NetNTLM credentials for [Brute Force](https://attack.mitre.org/techniques/T1110) or relay attacks that can gain code execution.(Citation: Impacket Tools)", "external_references": [{"description": "SecureAuth. (n.d.). Retrieved January 15, 2019.", "source_name": "Impacket Tools", "url": "https://www.secureauth.com/labs/open-source-tools/impacket"}], "id": "relationship--0318431e-ad44-44c7-97be-686d4efe79f4", "modified": "2026-04-29T14:23:05.907Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "spec_version": "2.1", "target_ref": "attack-pattern--650c784b-7504-4df7-ab2c-4ea882384d1e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23737', 0, 80, '09-mitre-attack', 'retrieved', 'E88167EBD7CCA399EE7C66CCBEEFB599C70ED1C7676F75E9FC2EDEFF5B18C785', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
