VALUES ('doc-09-mitre-attack-p0-23738', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-31T01:39:56.551Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Impacket](https://attack.mitre.org/software/S0357) can be used to sniff network traffic via an interface or raw socket.(Citation: Impacket Tools)", "external_references": [{"description": "SecureAuth. (n.d.). Retrieved January 15, 2019.", "source_name": "Impacket Tools", "url": "https://www.secureauth.com/labs/open-source-tools/impacket"}], "id": "relationship--191d6679-d6a8-42e3-b5ff-84a8d5bfb1dd", "modified": "2026-04-29T14:23:05.939Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "spec_version": "2.1", "target_ref": "attack-pattern--3257eb21-f9a7-4430-8de1-d8b6e288f529", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23738', 0, 58, '09-mitre-attack', 'retrieved', '6B9C76EAD2FE8EED7639D72C82E885A35D0613FBB0A5E0AA4108C9D83344DD09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
