VALUES ('doc-09-mitre-attack-p0-23739', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-31T01:39:56.555Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Impacket](https://attack.mitre.org/software/S0357) modules like GetUserSPNs can be used to get Service Principal Names (SPNs) for user accounts. The output is formatted to be compatible with cracking tools like John the Ripper and Hashcat.(Citation: Impacket Tools)", "external_references": [{"description": "SecureAuth. (n.d.). Retrieved January 15, 2019.", "source_name": "Impacket Tools", "url": "https://www.secureauth.com/labs/open-source-tools/impacket"}], "id": "relationship--5d4113cb-f652-4214-9585-388422528960", "modified": "2026-04-29T14:23:06.052Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "spec_version": "2.1", "target_ref": "attack-pattern--f2877f7f-9a4c-4251-879f-1224e3006bee", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23739', 0, 76, '09-mitre-attack', 'retrieved', '16C3ACDF32FAAD7394555E3C493A868F61081342DC55166845340379C45C9BCD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
