VALUES ('doc-09-mitre-attack-p0-23740', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-19T23:01:00.221Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "SecretsDump and [Mimikatz](https://attack.mitre.org/software/S0002) modules within [Impacket](https://attack.mitre.org/software/S0357) can perform credential dumping to obtain account and password information from NTDS.dit.(Citation: Impacket Tools)", "external_references": [{"description": "SecureAuth. (n.d.). Retrieved January 15, 2019.", "source_name": "Impacket Tools", "url": "https://www.secureauth.com/labs/open-source-tools/impacket"}], "id": "relationship--6d0fb103-d6f6-4259-a62f-296735020176", "modified": "2026-04-29T14:23:06.073Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "spec_version": "2.1", "target_ref": "attack-pattern--edf91964-b26e-4b4a-9600-ccacd7d7df24", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23740', 0, 62, '09-mitre-attack', 'retrieved', '171928222BF34E00E5EC5BCFB8C089FBCE8EE8369A2916FF699825135DD029F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
