VALUES ('doc-09-mitre-attack-p0-23790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-11T16:44:33.877Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Empire](https://attack.mitre.org/software/S0363) can use Inveigh to conduct name service poisoning for credential theft and associated relay attacks.(Citation: Github PowerShell Empire)(Citation: GitHub Inveigh)", "external_references": [{"description": "Schroeder, W., Warner, J., Nelson, M. (n.d.). Github PowerShellEmpire. Retrieved April 28, 2016.", "source_name": "Github PowerShell Empire", "url": "https://github.com/PowerShellEmpire/Empire"}, {"description": "Robertson, K. (2015, April 2). Inveigh: Windows PowerShell ADIDNS/LLMNR/mDNS/NBNS spoofer/man-in-the-middle tool. Retrieved March 11, 2019.", "source_name": "GitHub Inveigh", "url": "https://github.com/Kevin-Robertson/Inveigh"}], "id": "relationship--0537c342-77af-4626-bbe3-9360798a30d5", "modified": "2026-04-29T14:23:05.910Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--3433a9e8-1c47-4320-b9bf-ed449061d1c3", "spec_version": "2.1", "target_ref": "attack-pattern--650c784b-7504-4df7-ab2c-4ea882384d1e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23790', 0, 92, '09-mitre-attack', 'retrieved', '08CF6C2664EF36D08B3C4B7CE9840D3C1959147B874F3B38768B9F64969D7828', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
