VALUES ('doc-09-mitre-attack-p0-23791', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-11T20:01:20.330Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Empire](https://attack.mitre.org/software/S0363) can acquire network configuration information like DNS servers, public IP, and network proxies used by a host.(Citation: Github PowerShell Empire)(Citation: Talos Frankenstein June 2019)", "external_references": [{"description": "Adamitis, D. et al. (2019, June 4). It''s alive: Threat actors cobble together open-source pieces into monstrous Frankenstein campaign. Retrieved May 11, 2020.", "source_name": "Talos Frankenstein June 2019", "url": "https://blog.talosintelligence.com/2019/06/frankenstein-campaign.html"}, {"description": "Schroeder, W., Warner, J., Nelson, M. (n.d.). Github PowerShellEmpire. Retrieved April 28, 2016.", "source_name": "Github PowerShell Empire", "url": "https://github.com/PowerShellEmpire/Empire"}], "id": "relationship--07db5f41-fc53-47e6-ae7b-755a4acc9e62", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--3433a9e8-1c47-4320-b9bf-ed449061d1c3", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23791', 0, 106, '09-mitre-attack', 'retrieved', '5BD40DC4CCB048A49B4E91313EA34ED5D13BC674CA32A2C8FE8641FBAD2A6CD3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
