VALUES ('doc-09-mitre-attack-p0-23865', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-11T20:38:18.398Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FRP](https://attack.mitre.org/software/S1144) can tunnel SSH and Unix Domain Socket communications over TCP between external nodes and exposed resources behind firewalls or NAT.(Citation: FRP GitHub)", "external_references": [{"description": "fatedier. (n.d.). What is frp?. Retrieved July 10, 2024.", "source_name": "FRP GitHub", "url": "https://github.com/fatedier/frp"}], "id": "relationship--6ad38475-9375-4c8e-a15d-1a2f5ec6d4b7", "modified": "2026-04-29T14:23:06.070Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--36dd807e-b5bc-4c3e-91ed-80682360148c", "spec_version": "2.1", "target_ref": "attack-pattern--4fe28b27-b13c-453e-a386-c2ef362a573b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23865', 0, 68, '09-mitre-attack', 'retrieved', '18333CEC2810662C88A662D8F8D960BE447F601D6D28753E42D40639F7506696', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
