VALUES ('doc-09-mitre-attack-p0-23866', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-12T18:25:16.678Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FRP](https://attack.mitre.org/software/S1144) can be configured to only accept TLS connections.(Citation: FRP GitHub)", "external_references": [{"description": "fatedier. (n.d.). What is frp?. Retrieved July 10, 2024.", "source_name": "FRP GitHub", "url": "https://github.com/fatedier/frp"}], "id": "relationship--7728a470-8019-4120-b7a3-59bdcf5f472d", "modified": "2026-04-29T14:23:06.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--36dd807e-b5bc-4c3e-91ed-80682360148c", "spec_version": "2.1", "target_ref": "attack-pattern--bf176076-b789-408e-8cba-7275e81c0ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23866', 0, 56, '09-mitre-attack', 'retrieved', 'F11650F3573024466CA35E7DB287974B03DC163A23920453052F16552E5841C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
