VALUES ('doc-09-mitre-attack-p0-23867', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-12T18:55:14.187Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "As part of load balancing [FRP](https://attack.mitre.org/software/S1144) can set `healthCheck.type = \"tcp\"` or `healthCheck.type = \"http\"` to check service status on specific hosts with TCPing or an HTTP request.(Citation: FRP GitHub)", "external_references": [{"description": "fatedier. (n.d.). What is frp?. Retrieved July 10, 2024.", "source_name": "FRP GitHub", "url": "https://github.com/fatedier/frp"}], "id": "relationship--8035ec83-a439-442f-81d9-9306d2235d91", "modified": "2026-04-29T14:23:06.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--36dd807e-b5bc-4c3e-91ed-80682360148c", "spec_version": "2.1", "target_ref": "attack-pattern--e3a12395-188d-4051-9a16-ea8e14d07b88", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23867', 0, 75, '09-mitre-attack', 'retrieved', 'A68B505E2C438655540841E6125B60DE1B0D85FAD20D285445AA8567EA9C5476', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
