VALUES ('doc-09-mitre-attack-p0-23868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-12T18:08:00.092Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FRP](https://attack.mitre.org/software/S1144) can use a dashboard and U/I to display the status of connections from the FRP client and server.(Citation: FRP GitHub)", "external_references": [{"description": "fatedier. (n.d.). What is frp?. Retrieved July 10, 2024.", "source_name": "FRP GitHub", "url": "https://github.com/fatedier/frp"}], "id": "relationship--8b52e132-0b6b-4cd4-a3d2-a7d04a01dfcb", "modified": "2026-04-29T14:23:06.115Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--36dd807e-b5bc-4c3e-91ed-80682360148c", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23868', 0, 66, '09-mitre-attack', 'retrieved', 'A80C8A770F4DEC2BC41F6CBA63F8CD716D1C11F28629C150AD1BDA16886CCDBD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
