VALUES ('doc-09-mitre-attack-p0-23897', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-25T12:30:41.047Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RawDisk](https://attack.mitre.org/software/S0364) was used in [Shamoon](https://attack.mitre.org/software/S0140) to help overwrite components of disk structure like the MBR and disk partitions.(Citation: Palo Alto Shamoon Nov 2016)(Citation: Unit 42 Shamoon3 2018)", "external_references": [{"description": "Falcone, R.. (2016, November 30). Shamoon 2: Return of the Disttrack Wiper. Retrieved January 11, 2017.", "source_name": "Palo Alto Shamoon Nov 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/11/unit42-shamoon-2-return-disttrack-wiper/"}, {"description": "Falcone, R. (2018, December 13). Shamoon 3 Targets Oil and Gas Organization. Retrieved March 14, 2019.", "source_name": "Unit 42 Shamoon3 2018", "url": "https://unit42.paloaltonetworks.com/shamoon-3-targets-oil-gas-organization/"}], "id": "relationship--6add4de1-3af8-4994-b65f-ccb13fdd703a", "modified": "2026-04-29T14:23:06.070Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--3ffbdc1f-d2bf-41ab-91a2-c7b857e98079", "spec_version": "2.1", "target_ref": "attack-pattern--0af0ca99-357d-4ba1-805f-674fdfb7bef9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23897', 0, 106, '09-mitre-attack', 'retrieved', 'E6EBFF84FACCC1929EF7F487F66B071FEAAF4537E2ADD067A9CEC55D2C7A88D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
