VALUES ('doc-09-mitre-attack-p0-23898', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-29T16:48:43.877Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RawDisk](https://attack.mitre.org/software/S0364) has been used to directly access the hard disk to help overwrite arbitrarily sized portions of disk content.(Citation: Novetta Blockbuster Destructive Malware)", "external_references": [{"description": "Novetta Threat Research Group. (2016, February 24). Operation Blockbuster: Destructive Malware Report. Retrieved November 17, 2024.", "source_name": "Novetta Blockbuster Destructive Malware", "url": "https://web.archive.org/web/20160303200515/https:/operationblockbuster.com/wp-content/uploads/2016/02/Operation-Blockbuster-Destructive-Malware-Report.pdf"}], "id": "relationship--7fa1a7c8-0dfb-4bd5-a34f-509ba24da5be", "modified": "2026-04-29T14:23:06.100Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--3ffbdc1f-d2bf-41ab-91a2-c7b857e98079", "spec_version": "2.1", "target_ref": "attack-pattern--fb640c43-aa6b-431e-a961-a279010424ac", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23898', 0, 77, '09-mitre-attack', 'retrieved', 'FA57977694545F496951335B72B56C9CB0899818D59CFC15CE90D74654CDB5E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
