VALUES ('doc-09-mitre-attack-p0-23949', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-30T13:04:41.079Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Rclone](https://attack.mitre.org/software/S1040) \"chunker\" overlay supports splitting large files in smaller chunks during upload to circumvent size limits.(Citation: Rclone)(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}, {"description": "Nick Craig-Wood. (n.d.). Rclone syncs your files to cloud storage. Retrieved August 30, 2022.", "source_name": "Rclone", "url": "https://rclone.org"}], "id": "relationship--b351cd80-323d-4e67-a539-547a76d9e257", "modified": "2026-04-29T14:23:06.170Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--59096109-a1dd-463b-87e7-a8d110fe3a79", "spec_version": "2.1", "target_ref": "attack-pattern--c3888c54-775d-4b2f-b759-75a2ececcbfd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23949', 0, 95, '09-mitre-attack', 'retrieved', 'E29083A78BB942B8FA61451D2F4856D45220C2B5F3F678ADEB83102F462CC29A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
