VALUES ('doc-09-mitre-attack-p0-23954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[netsh](https://attack.mitre.org/software/S0108) can be used to disable local firewall settings.(Citation: TechNet Netsh)(Citation: TechNet Netsh Firewall)", "external_references": [{"description": "Microsoft. (n.d.). Using Netsh. Retrieved February 13, 2017.", "source_name": "TechNet Netsh", "url": "https://technet.microsoft.com/library/bb490939.aspx"}, {"description": "Microsoft. (2009, June 3). Netsh Commands for Windows Firewall. Retrieved April 20, 2016.", "source_name": "TechNet Netsh Firewall", "url": "https://technet.microsoft.com/en-us/library/cc771046(v=ws.10).aspx"}], "id": "relationship--35edfce6-c395-4dcd-b5be-848860f68d23", "modified": "2026-04-29T14:23:05.993Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--5a63f900-5e7e-4928-a746-dd4558e1df71", "spec_version": "2.1", "target_ref": "attack-pattern--eec096b8-c207-43df-b6c1-11523861e452", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23954', 0, 78, '09-mitre-attack', 'retrieved', 'EB844567CCD9D03163C883422B3F1FB122540D8D4FAC2225EF83C82AB84F31E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
