VALUES ('doc-09-mitre-attack-p0-24100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-04T16:05:33.564Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[attrib](https://attack.mitre.org/software/S1176) can be used to make files or directories hidden.(Citation: Microsoft attrib 2023)(Citation: gbhackers Darkgate Malware 2024)(Citation: LogRhythm WannaCry)(Citation: Checkpoint WannaCry 2017)(Citation: Unit42 ComboJack 2018) ", "external_references": [{"description": "Divya. (2024, April 30). Darkgate Malware Leveraging Autohotkey Following Teams. Retrieved November 22, 2024.", "source_name": "gbhackers Darkgate Malware 2024", "url": "https://gbhackers.com/darkgate-malware-leveraging/"}, {"description": "Levene, B., Grunzweig, J. (2018, March 5). Sure, I’ll take that! New ComboJack Malware Alters Clipboards to Steal Cryptocurrency. Retrieved November 25, 2024.", "source_name": "Unit42 ComboJack 2018", "url": "https://unit42.paloaltonetworks.com/unit42-sure-ill-take-new-combojack-malware-alters-clipboards-steal-cryptocurrency/"}, {"description": "Noerenberg, E., Costis, A., and Quist, N. (2017, May 16). A Technical Analysis of WannaCry Ransomware. Retrieved December 8, 2024.", "source_name": "LogRhythm WannaCry", "url": "https://web.archive.org/web/20230522041200/https://logrhythm.com/blog/a-technical-analysis-of-wannacry-ransomware/"}, {"description": "Pal, P. (2017, May 16). CRYING IS FUTILE: SandBlast Forensic Analysis of WannaCry. Retrieved November 22, 2024.", "source_name": "Checkpoint WannaCry 2017", "url": "https://blog.checkpoint.com/research/crying-futile-sandblast-forensic-analysis-wannacry/"}, {"description": "Xelu86, et al. (2023, September 25). attrib. Retrieved November 22, 2024.", "source_name": "Microsoft attrib 2023", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/attrib"}], "id": "relationship--cc602d8f-9abf-4617-b33d-34bf91130f0c", "modified": "2026-04-