VALUES ('doc-09-mitre-attack-p0-24121', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Forfiles](https://attack.mitre.org/software/S0193) can be used to subvert controls and possibly conceal command execution by not directly invoking [cmd](https://attack.mitre.org/software/S0106).(Citation: VectorSec ForFiles Aug 2017)(Citation: Evi1cg Forfiles Nov 2017)", "external_references": [{"description": "Evi1cg. (2017, November 26). block cmd.exe ? try this :. Retrieved September 12, 2024.", "source_name": "Evi1cg Forfiles Nov 2017", "url": "https://x.com/Evi1cg/status/935027922397573120"}, {"description": "vector_sec. (2017, August 11). Defenders watching launches of cmd? What about forfiles?. Retrieved September 12, 2024.", "source_name": "VectorSec ForFiles Aug 2017", "url": "https://x.com/vector_sec/status/896049052642533376"}], "id": "relationship--8b746637-fef8-474e-8960-822d758fb9b3", "modified": "2026-04-29T14:23:06.116Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--90ec2b22-7061-4469-b539-0989ec4f96c2", "spec_version": "2.1", "target_ref": "attack-pattern--3b0e52ce-517a-4614-a523-1bd5deef6c5e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24121', 0, 101, '09-mitre-attack', 'retrieved', '2139FF96949D5C96F59C01ECA4A34B4579BF35719C8522AFE9A9475A94DC4E10', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
