VALUES ('doc-09-mitre-attack-p0-24162', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-19T23:37:02.559Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mimikatz](https://attack.mitre.org/software/S0002) performs credential dumping to obtain account and password information useful in gaining access to additional systems and enterprise network resources. It contains functionality to acquire information about credentials in many ways, including from the credential vault and DPAPI.(Citation: Deply Mimikatz)(Citation: GitHub Mimikatz lsadump Module)(Citation: Directory Services Internals DPAPI Backup Keys Oct 2015)(Citation: NCSC Joint Report Public Tools)(Citation: Cobalt Strike Manual 4.3 November 2020)\t", "external_references": [{"description": "Deply, B. (n.d.). Mimikatz. Retrieved September 29, 2015.", "source_name": "Deply Mimikatz", "url": "https://github.com/gentilkiwi/mimikatz"}, {"description": "Deply, B., Le Toux, V. (2016, June 5). module ~ lsadump. Retrieved August 7, 2017.", "source_name": "GitHub Mimikatz lsadump Module", "url": "https://github.com/gentilkiwi/mimikatz/wiki/module-~-lsadump"}, {"description": "Grafnetter, M. (2015, October 26). Retrieving DPAPI Backup Keys from Active Directory. Retrieved December 19, 2017.", "source_name": "Directory Services Internals DPAPI Backup Keys Oct 2015", "url": "https://www.dsinternals.com/en/retrieving-dpapi-backup-keys-from-active-directory/"}, {"description": "The Australian Cyber Security Centre (ACSC), the Canadian Centre for Cyber Security (CCCS), the New Zealand National Cyber Security Centre (NZ NCSC), CERT New Zealand, the UK National Cyber Security Centre (UK NCSC) and the US National Cybersecurity and Communications Integration Center (NCCIC). (2018, October 11). Joint report on publicly available hacking tools. Retrieved March 11, 2019.", "source_name": "NCSC Joint Report Public Tools", "url": "https://www.ncsc.gov.uk/report/joint-report-on-publicly-available-hacking-tools"}, {"description": "Strategic Cyber LLC. (2020, November 5). Cobalt Strike: Advanced Threat Tactics for Penetration Testers. Retrieved April 13, 2021.", "source_name": "Cobalt Strike Manual 4.3 November 2020", "url": "https://web.archive.org/web/20210708035426/https://www.cobaltstrike.com/downloads/csmanual43.pdf"}], "id": "relationship--11d0f089-6dc7-4468-b186-e1a8b621051b", "modified": "2026-04-29T14:23:05.928Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24162', 0, 253, '09-mitre-attack', 'retrieved', '54D975A05B923D5BEE7C2863B62209E0689B313B1BCCDFF2BA4E9D5367A3B966', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
