VALUES ('doc-09-mitre-attack-p0-24164', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mimikatz](https://attack.mitre.org/software/S0002)''s CRYPTO::Extract module can extract keys by interacting with Windows cryptographic application programming interface (API) functions.(Citation: Adsecurity Mimikatz Guide)", "external_references": [{"description": "Metcalf, S. (2015, November 13). Unofficial Guide to Mimikatz & Command Reference. Retrieved December 23, 2015.", "source_name": "Adsecurity Mimikatz Guide", "url": "https://adsecurity.org/?page_id=1821"}], "id": "relationship--1c5b8ff2-400a-4e0f-a819-3cc8f1bc76b8", "modified": "2026-04-29T14:23:05.943Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "spec_version": "2.1", "target_ref": "attack-pattern--60b508a1-6a5e-46b1-821a-9f7b78752abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24164', 0, 72, '09-mitre-attack', 'retrieved', 'DF3CB957E9805F4D3913B089D4FC47BA4443A9E496E417D3E22FE37F2E11F39B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
