VALUES ('doc-09-mitre-attack-p0-24166', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Mimikatz](https://attack.mitre.org/software/S0002) credential dumper contains an implementation of an SSP.(Citation: Deply Mimikatz)", "external_references": [{"description": "Deply, B. (n.d.). Mimikatz. Retrieved September 29, 2015.", "source_name": "Deply Mimikatz", "url": "https://github.com/gentilkiwi/mimikatz"}], "id": "relationship--41f04732-8fdc-4b2f-9e22-7b78ff650e5d", "modified": "2026-04-29T14:23:06.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "spec_version": "2.1", "target_ref": "attack-pattern--5095a853-299c-4876-abd7-ac0050fb5462", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24166', 0, 56, '09-mitre-attack', 'retrieved', '3E1F2EEFF41E7967DC289509DE2BF15D4709FC6FA8E024A31736D9F16D5F2A3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
