VALUES ('doc-09-mitre-attack-p0-24174', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-23T17:38:03.062Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mimikatz](https://attack.mitre.org/software/S0002) contains functionality to acquire credentials from the Windows Credential Manager.(Citation: Delpy Mimikatz Crendential Manager)", "external_references": [{"description": "Delpy, B. (2017, December 12). howto ~ credential manager saved credentials. Retrieved November 23, 2020.", "source_name": "Delpy Mimikatz Crendential Manager", "url": "https://github.com/gentilkiwi/mimikatz/wiki/howto-~-credential-manager-saved-credentials"}], "id": "relationship--c92047b8-50d6-4fde-8acd-98132dcdc32f", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "spec_version": "2.1", "target_ref": "attack-pattern--d336b553-5da9-46ca-98a8-0b23f49fb447", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24174', 0, 68, '09-mitre-attack', 'retrieved', '910BC38BD93D742C165C99E2D7E0B9CE8BF85C87F3AE0732DEDACD41B80CBBDF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
