VALUES ('doc-09-mitre-attack-p0-24340', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QuasarRAT](https://attack.mitre.org/software/S0262) uses AES with a hardcoded pre-shared key to encrypt network communication.(Citation: GitHub QuasarRAT)(Citation: Volexity Patchwork June 2018)(Citation: CISA AR18-352A Quasar RAT December 2018)", "external_references": [{"description": "CISA. (2018, December 18). Analysis Report (AR18-352A) Quasar Open-Source Remote Administration Tool. Retrieved August 1, 2022.", "source_name": "CISA AR18-352A Quasar RAT December 2018", "url": "https://www.cisa.gov/uscert/ncas/analysis-reports/AR18-352A"}, {"description": "MaxXor. (n.d.). QuasarRAT. Retrieved July 10, 2018.", "source_name": "GitHub QuasarRAT", "url": "https://github.com/quasar/QuasarRAT"}, {"description": "Meltzer, M, et al. (2018, June 07). Patchwork APT Group Targets US Think Tanks. Retrieved July 16, 2018.", "source_name": "Volexity Patchwork June 2018", "url": "https://www.volexity.com/blog/2018/06/07/patchwork-apt-group-targets-us-think-tanks/"}], "id": "relationship--2f3ff7c9-ea14-45ad-b295-6f2f3c40cff7", "modified": "2026-04-29T14:23:05.970Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--da04ac30-27da-4959-a67d-450ce47d9470", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24340', 0, 119, '09-mitre-attack', 'retrieved', 'FC30B38C9EBC3D2CF1A682EB707F3632C46A21847CB5AA6D4741AFC7F97DAAD5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTU