VALUES ('doc-09-mitre-attack-p0-24341', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T19:05:41.430Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QuasarRAT](https://attack.mitre.org/software/S0262) can obtain passwords from common web browsers.(Citation: GitHub QuasarRAT)(Citation: Volexity Patchwork June 2018)(Citation: Kaspersky BlindEagle AUG 2024)\n", "external_references": [{"description": "Global Research & Analysis Team, Kaspersky. (2024, August 19). BlindEagle flying high in Latin America. Retrieved April 16, 2026.", "source_name": "Kaspersky BlindEagle AUG 2024", "url": "https://securelist.com/blindeagle-apt/113414/"}, {"description": "MaxXor. (n.d.). QuasarRAT. Retrieved July 10, 2018.", "source_name": "GitHub QuasarRAT", "url": "https://github.com/quasar/QuasarRAT"}, {"description": "Meltzer, M, et al. (2018, June 07). Patchwork APT Group Targets US Think Tanks. Retrieved July 16, 2018.", "source_name": "Volexity Patchwork June 2018", "url": "https://www.volexity.com/blog/2018/06/07/patchwork-apt-group-targets-us-think-tanks/"}], "id": "relationship--360f1c0d-c6ec-4d49-92a0-e8ce63559960", "modified": "2026-04-29T14:23:05.993Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--da04ac30-27da-4959-a67d-450ce47d9470", "spec_version": "2.1", "target_ref": "attack-pattern--58a3e6aa-4453-4cc8-a51f-4befe80b31a8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24341', 0, 114, '09-mitre-attack', 'retrieved', '95B72AF42E908CB6A01134EC1FA627157A5FD4B6FD7899AAC2B5C5A68A4D55CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
