VALUES ('doc-09-mitre-attack-p0-24342', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-22T14:12:22.578Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If the [QuasarRAT](https://attack.mitre.org/software/S0262) client process does not have administrator privileges it will add a registry key to `HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run` for persistence.(Citation: GitHub QuasarRAT)(Citation: CISA AR18-352A Quasar RAT December 2018) ", "external_references": [{"description": "CISA. (2018, December 18). Analysis Report (AR18-352A) Quasar Open-Source Remote Administration Tool. Retrieved August 1, 2022.", "source_name": "CISA AR18-352A Quasar RAT December 2018", "url": "https://www.cisa.gov/uscert/ncas/analysis-reports/AR18-352A"}, {"description": "MaxXor. (n.d.). QuasarRAT. Retrieved July 10, 2018.", "source_name": "GitHub QuasarRAT", "url": "https://github.com/quasar/QuasarRAT"}], "id": "relationship--3e3a5bf5-1e90-45d2-b90a-3b919f5425d5", "modified": "2026-04-29T14:23:06.010Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--da04ac30-27da-4959-a67d-450ce47d9470", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24342', 0, 98, '09-mitre-attack', 'retrieved', '99BC5FEBB77C15343AB68D523A09C663E27A6869CF51BBC6BD54B48F13B47BD6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
