VALUES ('doc-09-mitre-attack-p0-24348', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-02T18:03:38.458Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\n[QuasarRAT](https://attack.mitre.org/software/S0262) has the ability to set file attributes to \"hidden\" to hide files from the compromised user''s view in Windows File Explorer.(Citation: CISA AR18-352A Quasar RAT December 2018)", "external_references": [{"description": "CISA. (2018, December 18). Analysis Report (AR18-352A) Quasar Open-Source Remote Administration Tool. Retrieved August 1, 2022.", "source_name": "CISA AR18-352A Quasar RAT December 2018", "url": "https://www.cisa.gov/uscert/ncas/analysis-reports/AR18-352A"}], "id": "relationship--5d96e66b-372a-43de-892d-30086d7ff00e", "modified": "2026-04-29T14:23:06.053Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--da04ac30-27da-4959-a67d-450ce47d9470", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24348', 0, 84, '09-mitre-attack', 'retrieved', '8624E1EF705BE4D3B227548BE61F609F6A4E3DC16EA773932289A6CE14AA66B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
