VALUES ('doc-09-mitre-attack-p0-24370', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Traffic traversing the [Tor](https://attack.mitre.org/software/S0183) network will be forwarded to multiple nodes before exiting the [Tor](https://attack.mitre.org/software/S0183) network and continuing on to its intended destination.(Citation: Dingledine Tor The Second-Generation Onion Router)", "external_references": [{"description": "Roger Dingledine, Nick Mathewson and Paul Syverson. (2004). Tor: The Second-Generation Onion Router. Retrieved December 21, 2017.", "source_name": "Dingledine Tor The Second-Generation Onion Router", "url": "http://www.dtic.mil/dtic/tr/fulltext/u2/a465464.pdf"}], "id": "relationship--92e4cc06-5708-4486-92cc-0d25d9a755d4", "modified": "2026-04-29T14:23:06.125Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--ed7d0cb1-87a6-43b4-9f46-ef1bc56d6c68", "spec_version": "2.1", "target_ref": "attack-pattern--a782ebe2-daba-42c7-bc82-e8e9d923162d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24370', 0, 86, '09-mitre-attack', 'retrieved', '2F832D40EF7C7987D426EF08A51D1FA6007E22917A39FD1E4AC0FEA359FD7386', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
