VALUES ('doc-09-mitre-attack-p0-24380', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:16:34.647Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quick Assist](https://attack.mitre.org/software/S1209) communicates over TCP 443 via HTTPS to a remote session server, under which RDP traffic is transferred.(Citation: Microsoft Quick Assist 2024)", "external_references": [{"description": "Microsoft. (2024, September 4). Use Quick Assist to help users. Retrieved March 14, 2025.", "source_name": "Microsoft Quick Assist 2024", "url": "https://learn.microsoft.com/en-us/windows/client-management/client-tools/quick-assist"}], "id": "relationship--4dfb8cee-0807-46db-aba1-c7024037c712", "modified": "2026-04-29T14:23:06.031Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--fcdb30de-5449-4777-a4f4-922e71f65932", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24380', 0, 75, '09-mitre-attack', 'retrieved', 'F868C8479F49430B2170666D5DE0439C239C9572683078FAE1FD0F3ECC14D9B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
