VALUES ('doc-09-mitre-attack-p0-24381', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:14:29.422Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quick Assist](https://attack.mitre.org/software/S1209) allows for the remote administrator to take screenshots of the running system.(Citation: Microsoft Quick Assist 2024)", "external_references": [{"description": "Microsoft. (2024, September 4). Use Quick Assist to help users. Retrieved March 14, 2025.", "source_name": "Microsoft Quick Assist 2024", "url": "https://learn.microsoft.com/en-us/windows/client-management/client-tools/quick-assist"}], "id": "relationship--67731257-6a0a-46cf-8f7e-cc6793d5fdb9", "modified": "2026-04-29T14:23:06.066Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--fcdb30de-5449-4777-a4f4-922e71f65932", "spec_version": "2.1", "target_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24381', 0, 70, '09-mitre-attack', 'retrieved', 'DEE0DD139DC411EFB1839E21CBB2F8146A71A3C897B9FB6E152CE30E73636BCD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
