VALUES ('doc-09-mitre-attack-p0-24382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:15:19.239Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quick Assist](https://attack.mitre.org/software/S1209) allows for the remote administrator to view the interactive session of the running machine, including full screen activity.(Citation: Microsoft Quick Assist 2024)(Citation: Microsoft Storm-1811 2024)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, May 15). Threat actors misusing Quick Assist in social engineering attacks leading to ransomware. Retrieved March 14, 2025.", "source_name": "Microsoft Storm-1811 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/05/15/threat-actors-misusing-quick-assist-in-social-engineering-attacks-leading-to-ransomware/"}, {"description": "Microsoft. (2024, September 4). Use Quick Assist to help users. Retrieved March 14, 2025.", "source_name": "Microsoft Quick Assist 2024", "url": "https://learn.microsoft.com/en-us/windows/client-management/client-tools/quick-assist"}], "id": "relationship--a4485212-aea0-4cf0-b7f1-79b3048d910f", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--fcdb30de-5449-4777-a4f4-922e71f65932", "spec_version": "2.1", "target_ref": "attack-pattern--6faf650d-bf31-4eb4-802d-1000cf38efaf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24382', 0, 108, '09-mitre-attack', 'retrieved', 'DE5CBC87FF0AF4D67ABBFEA62CA4A9A33FCD888B4872F851A4DB0B506120CA51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
