VALUES ('doc-09-mitre-attack-p0-24383', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PsExec](https://attack.mitre.org/software/S0029), a tool that has been used by adversaries, writes programs to the ADMIN$ network share to execute commands on remote systems.(Citation: PsExec Russinovich)", "external_references": [{"description": "Russinovich, M. (2004, June 28). PsExec. Retrieved December 17, 2015.", "source_name": "PsExec Russinovich", "url": "http://windowsitpro.com/systems-management/psexec"}], "id": "relationship--27102940-8ec1-42ad-98e5-57dc24b572eb", "modified": "2026-04-29T14:23:05.958Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--ff6caf67-ea1f-4895-b80e-4bb0fc31c6db", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24383', 0, 70, '09-mitre-attack', 'retrieved', '76FF031B8A9E908BCE9304201E578991EF9956D096CC2D684688FFC1C651E682', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
