VALUES ('doc-09-mitre-attack-p0-24384', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-07T21:12:23.440Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PsExec](https://attack.mitre.org/software/S0029) can leverage Windows services to escalate privileges from administrator to SYSTEM with the -s argument.(Citation: Russinovich Sysinternals)", "external_references": [{"description": "Russinovich, M. (2014, May 2). Windows Sysinternals PsExec v2.11. Retrieved May 13, 2015.", "source_name": "Russinovich Sysinternals", "url": "https://technet.microsoft.com/en-us/sysinternals/bb897553.aspx"}], "id": "relationship--43b00ad2-2d54-4ca9-a0a2-a0cb1a5fa7ff", "modified": "2026-04-29T14:23:06.018Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--ff6caf67-ea1f-4895-b80e-4bb0fc31c6db", "spec_version": "2.1", "target_ref": "attack-pattern--2959d63f-73fd-46a1-abd2-109d7dcede32", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24384', 0, 67, '09-mitre-attack', 'retrieved', '64B170449E40DFF4351B3DAF53E02FEC3F0E261366BDAC56F7C289A2F52BF011', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
