VALUES ('doc-09-mitre-attack-p0-24385', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-20T19:20:27.670Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PsExec](https://attack.mitre.org/software/S0029) can be used to download or upload a file over a network share.(Citation: PsExec Russinovich)", "external_references": [{"description": "Russinovich, M. (2004, June 28). PsExec. Retrieved December 17, 2015.", "source_name": "PsExec Russinovich", "url": "http://windowsitpro.com/systems-management/psexec"}], "id": "relationship--9f5c68fe-a32e-405d-ae58-0965f04855cb", "modified": "2026-04-29T14:23:06.142Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--ff6caf67-ea1f-4895-b80e-4bb0fc31c6db", "spec_version": "2.1", "target_ref": "attack-pattern--bf90d72c-c00b-45e3-b3aa-68560560d4c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24385', 0, 62, '09-mitre-attack', 'retrieved', '269CDBFCACD65F1A3BD121ABD1E16D6265295FDE97CDB175357E35F3C2A1DC20', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
