VALUES ('doc-09-mitre-attack-p0-24386', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Microsoft Sysinternals [PsExec](https://attack.mitre.org/software/S0029) is a popular administration tool that can be used to execute binaries on remote systems using a temporary Windows service.(Citation: Russinovich Sysinternals)", "external_references": [{"description": "Russinovich, M. (2014, May 2). Windows Sysinternals PsExec v2.11. Retrieved May 13, 2015.", "source_name": "Russinovich Sysinternals", "url": "https://technet.microsoft.com/en-us/sysinternals/bb897553.aspx"}], "id": "relationship--a66aff09-0635-44a3-b591-a530a25c9012", "modified": "2026-04-29T14:23:06.152Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "tool--ff6caf67-ea1f-4895-b80e-4bb0fc31c6db", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24386', 0, 74, '09-mitre-attack', 'retrieved', '2652A99A2B5631BB5B9E3DD9023977553DBE24E26325456DB43F261643AC67DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
