VALUES ('doc-09-mitre-attack-p0-24388', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-07T20:53:38.145Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) can compress and encrypt data and exfiltrate it via POST to scan.aquasecurtiy[.]org. If that method fails it attempts to use a stolen GITHUB_TOKEN to create a repo and exfiltrate the data there.(Citation: Wiz Trivy Compromise MAR 2026)", "external_references": [{"description": "McCarthy, R. (2026, March 20). Trivy Compromised: Everything You Need to Know about the Latest Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz Trivy Compromise MAR 2026", "url": "https://www.wiz.io/blog/trivy-compromised-teampcp-supply-chain-attack"}], "id": "relationship--ace245e2-6972-4247-9b08-4c6a375cfce7", "modified": "2026-07-07T20:53:38.145Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fe5b2f0f-8fdc-459d-85b7-dd45c0217a0c", "spec_version": "2.1", "target_ref": "attack-pattern--774a3188-6ba9-4dc4-879d-d54ee48a5ce9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24388', 0, 101, '09-mitre-attack', 'retrieved', '92C00F486B9526E917BA350B751AF93EBF1F143EB222C83E4BF421943896762E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
