VALUES ('doc-09-mitre-attack-p0-24428', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-14T19:48:36.915Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) has abused the shell script files entrypoint.sh (in trivy-action) and setup.sh (in ast-github-action/2.3.28) for discovery and credential harvesting.(Citation: Sysdig TeamPCP MAR 2026) (Citation: Palo Alto TeamPCP MAR 2026)\n", "external_references": [{"description": "Sysdig Threat Research Team. (2026, March 23). TeamPCP expands: Supply chain compromise spreads from Trivy to Checkmarx GitHub Actions. Retrieved July 1, 2026.", "source_name": "Sysdig TeamPCP MAR 2026", "url": "https://www.sysdig.com/blog/teampcp-expands-supply-chain-compromise-spreads-from-trivy-to-checkmarx-github-actions"}, {"description": "Unit 42. (2026, March 31). Weaponizing the Protectors: TeamPCP’s Multi-Stage Supply Chain Attack on Security Infrastructure. Retrieved July 1, 2026.", "source_name": "Palo Alto TeamPCP MAR 2026", "url": "https://unit42.paloaltonetworks.com/teampcp-supply-chain-attacks/"}], "id": "relationship--d586b2af-ad13-48f2-b7d6-126172d25f9a", "modified": "2026-07-29T22:33:03.776Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fe5b2f0f-8fdc-459d-85b7-dd45c0217a0c", "spec_version": "2.1", "target_ref": "attack-pattern--a9d4b653-6915-42af-98b2-5758c4ceee56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24428', 0, 121, '09-mitre-attack', 'retrieved', '7340F437D68FE7EC7CC560E79170ACA80F89498FEB84C99F5463439C357BCF86', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
