VALUES ('doc-09-mitre-attack-p0-24430', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-08T20:07:47.803Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) has checked if it is running on a developer machine (rather than GitHub Actions) before executing a Python script for persistence. The script has also polled C2 every 50 minutes for additional payloads and aborted if the returned value contained YouTube.(Citation: Aqua Security Blog Trivy Compromise APR 2026)(Citation: Wiz TeamPCP KICS MAR 2026) ", "external_references": [{"description": "Aqua Team. (2026, April 1). Update: Ongoing Investigation and Continued Remediation. Retrieved July 1, 2026.", "source_name": "Aqua Security Blog Trivy Compromise APR 2026", "url": "https://www.aquasec.com/blog/trivy-supply-chain-attack-what-you-need-to-know"}, {"description": "McCarthy, R., Haughom, J., Read, B. (2026, March 23). KICS GitHub Action Compromised: TeamPCP Strikes Again in Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz TeamPCP KICS MAR 2026", "url": "https://www.wiz.io/blog/teampcp-attack-kics-github-action"}], "id": "relationship--f2da1e7c-d5c2-4f1b-b58a-3650c758858a", "modified": "2026-07-29T22:37:23.597Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fe5b2f0f-8fdc-459d-85b7-dd45c0217a0c", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24430', 0, 146, '09-mitre-attack', 'retrieved', 'FAA476BCB09804E2E5AA25468E3BA3B1B3D1B86AD9A773C4B2BFBD33F27E90A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
