VALUES ('doc-09-mitre-attack-p0-24431', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-07T20:24:56.870Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) has detected if it is on a developer machine by checking if the environmental variable GITHUB_ACTIONS != “true”.(Citation: Wiz Trivy Compromise MAR 2026) [TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) has also identified readable memory regions on CI/CD runners and enumerated system information using `hostname` and `uname-a`.(Citation: Aqua Security Blog Trivy Compromise APR 2026)", "external_references": [{"description": "Aqua Team. (2026, April 1). Update: Ongoing Investigation and Continued Remediation. Retrieved July 1, 2026.", "source_name": "Aqua Security Blog Trivy Compromise APR 2026", "url": "https://www.aquasec.com/blog/trivy-supply-chain-attack-what-you-need-to-know"}, {"description": "McCarthy, R. (2026, March 20). Trivy Compromised: Everything You Need to Know about the Latest Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz Trivy Compromise MAR 2026", "url": "https://www.wiz.io/blog/trivy-compromised-teampcp-supply-chain-attack"}], "id": "relationship--f99c66b5-df6f-4097-b72b-82bbe3f5fe02", "modified": "2026-07-29T22:38:33.840Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fe5b2f0f-8fdc-459d-85b7-dd45c0217a0c", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24431', 0, 140, '09-mitre-attack', 'retrieved', '3A001D84A28B24779B0B2AB40C30F3F8D25DA60EE0013B2E343B7204DA9A482B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
