VALUES ('doc-09-mitre-attack-p0-24434', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-07T20:43:58.541Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamPCP Cloud Stealer](https://attack.mitre.org/software/S9041) has leveraged a persistence script that will sleep for five minutes before additional execution.(Citation: Wiz Trivy Compromise MAR 2026)(Citation: Aqua Security Blog Trivy Compromise APR 2026)(Citation: Wiz TeamPCP KICS MAR 2026)", "external_references": [{"description": "Aqua Team. (2026, April 1). Update: Ongoing Investigation and Continued Remediation. Retrieved July 1, 2026.", "source_name": "Aqua Security Blog Trivy Compromise APR 2026", "url": "https://www.aquasec.com/blog/trivy-supply-chain-attack-what-you-need-to-know"}, {"description": "McCarthy, R. (2026, March 20). Trivy Compromised: Everything You Need to Know about the Latest Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz Trivy Compromise MAR 2026", "url": "https://www.wiz.io/blog/trivy-compromised-teampcp-supply-chain-attack"}, {"description": "McCarthy, R., Haughom, J., Read, B. (2026, March 23). KICS GitHub Action Compromised: TeamPCP Strikes Again in Supply Chain Attack. Retrieved July 1, 2026.", "source_name": "Wiz TeamPCP KICS MAR 2026", "url": "https://www.wiz.io/blog/teampcp-attack-kics-github-action"}], "id": "relationship--01354b67-5cc4-4701-9dbf-e750076c5d5d", "modified": "2026-07-29T22:41:19.972Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fe5b2f0f-8fdc-459d-85b7-dd45c0217a0c", "spec_version": "2.1", "target_ref": "attack-pattern--a1df809c-7d0e-459f-8fe5-25474bab770b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24434', 0, 154, '09-mitre-