VALUES ('doc-09-mitre-attack-p0-24435', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-07-29T17:59:37.003Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mini Shai-Hulud](https://attack.mitre.org/software/S9043) has established persistence on macOS hosts by installing a gh-token-monitor daemon through LaunchAgent that polls GitHub every 60 seconds.(Citation: Wiz Mini Shai-Hulud MAY 2026)", "external_references": [{"description": "McCarthy, R., Cohen, A., and Read, B. (2026, May 12). Mini Shai-Hulud Strikes Again: TanStack + more npm Packages Compromised. Retrieved July 16, 2026.", "source_name": "Wiz Mini Shai-Hulud MAY 2026", "url": "https://www.wiz.io/blog/mini-shai-hulud-strikes-again-tanstack-more-npm-packages-compromised"}], "id": "relationship--0be2f567-71b1-4cae-a357-25f9e2109b9c", "modified": "2026-07-29T17:59:37.003Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f211b2e-c008-4cac-9ea8-29bd7edd50a4", "spec_version": "2.1", "target_ref": "attack-pattern--d10cbd34-42e3-45c0-84d2-535a09849584", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-24435', 0, 89, '09-mitre-attack', 'retrieved', '98594174F1C324820F0B8E8EAF8670B764F9999D7796205089BF53239BAC34B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
